import json,sys
d=json.load(sys.stdin)
for f in d['data']['__schema']['mutationType']['fields']:
    if f['name'] in ('userPromoteMember','userPromoteAdmin','userDemoteMember','userDemoteAdmin','userSuspend','userUnsuspend','userUpdate'):
        t=f['type']
        def walk(t,depth=0):
            if t is None: return None
            s=t.get('name') or ''
            if t.get('ofType'): s+= ' ' + walk(t['ofType'],depth+1)
            return s
        print(f['name'], '| args:', [(a['name'], a['type'].get('name') or (a['type'].get('ofType') or {}).get('name')) for a in f['args']], '| ret:', walk(t))
"

curl -s -X POST https://api.linear.app/graphql -H "Authorization: <TOKEN>" -H "Content-Type: application/json" -d '{"query":"{ __schema { types { name kind fields { name description type { name } } inputFields { name description } enumValues { name description } } } }"}' | python3 -c "
import json,sys
d=json.load(sys.stdin)
kw=['app','seat','license','role','member']
for t in d['data']['__schema']['types']:
    hits=[]
    for f in (t.get('fields') or []):
        s=(f['name']+' '+(f.get('description') or ''))
        if any(k in s.lower() for k in kw): hits.append('F:'+f['name']+'='+str(f['type'].get('name')))
    for f in (t.get('inputFields') or []):
        s=(f['name']+' '+(f.get('description') or ''))
        if any(k in s.lower() for k in kw): hits.append('I:'+f['name'])
    for e in (t.get('enumValues') or []):
        s=(e['name']+' '+(e.get('description') or ''))
        if any(k in s.lower() for k in kw): hits.append('E:'+e['name'])
    if hits:
        print(t['name'], '::', hits)
"
